-- Barre gets a picture like all the other lessons: the AI illustration of the studio (warm light, green walls, the
-- OCTOPUSH label with the lesson's name), instead of the real photo of the empty studio from 0136. Only if the
-- lesson still has that photo (one chosen in Admin → Lekce stays). The new picture is listed with the AI pictures,
-- so it shows the AI mark like the others.
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data")
VALUES ('ec959597-fbb1-4d76-aa7b-66f5990ae8c3', 'barre-ai.webp', 'image/webp', 1600, 900, 88600, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
UPDATE "class_types" SET "image_url" = '/media/ec959597-fbb1-4d76-aa7b-66f5990ae8c3.webp'
WHERE ("slug" = 'barre' OR lower("name") = 'barre') AND "image_url" = '/media/c03289c2-7b45-4d22-9683-980db5c1a1fe.webp';
--> statement-breakpoint
INSERT INTO "settings" ("key", "value") VALUES ('aiImages', '["/media/ec959597-fbb1-4d76-aa7b-66f5990ae8c3.webp"]'::jsonb)
ON CONFLICT ("key") DO UPDATE SET "value" = CASE
  WHEN jsonb_typeof("settings"."value") <> 'array' THEN EXCLUDED."value"
  WHEN "settings"."value" @> EXCLUDED."value" THEN "settings"."value"
  ELSE "settings"."value" || EXCLUDED."value"
END;
